// Two-factor authentication: time-based one-time passwords (TOTP, RFC 6238),
// as generated by authenticator apps (Google Authenticator, Aegis, 1Password,
// Bitwarden…), and single-use recovery codes.

import crypto from "node:crypto";

import { transaction } from "./db.js";

const PERIOD_MS = 30 * 1000;
const DIGITS = 6;
/** accepted clock drift, in periods, on each side */
const WINDOW = 1;
const RECOVERY_CODE_COUNT = 10;
const ISSUER = "Excalidraw Unchained";

const BASE32 = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567";

export const base32Encode = (bytes) => {
  let bits = 0;
  let value = 0;
  let output = "";
  for (const byte of bytes) {
    value = (value << 8) | byte;
    bits += 8;
    while (bits >= 5) {
      output += BASE32[(value >>> (bits - 5)) & 31];
      bits -= 5;
    }
  }
  if (bits > 0) {
    output += BASE32[(value << (5 - bits)) & 31];
  }
  return output;
};

export const base32Decode = (text) => {
  const clean = String(text)
    .replace(/[\s=-]/g, "")
    .toUpperCase();
  let bits = 0;
  let value = 0;
  const bytes = [];
  for (const char of clean) {
    const index = BASE32.indexOf(char);
    if (index === -1) {
      throw new Error("Invalid base32");
    }
    value = (value << 5) | index;
    bits += 5;
    if (bits >= 8) {
      bytes.push((value >>> (bits - 8)) & 255);
      bits -= 8;
    }
  }
  return Buffer.from(bytes);
};

export const generateTotpSecret = () => base32Encode(crypto.randomBytes(20));

/** HOTP (RFC 4226) for the given counter */
export const hotp = (secret, counter) => {
  const message = Buffer.alloc(8);
  message.writeUInt32BE(Math.floor(counter / 2 ** 32), 0);
  message.writeUInt32BE(counter % 2 ** 32, 4);
  const hmac = crypto
    .createHmac("sha1", base32Decode(secret))
    .update(message)
    .digest();
  const offset = hmac[hmac.length - 1] & 15;
  const code = (hmac.readUInt32BE(offset) & 0x7fffffff) % 10 ** DIGITS;
  return String(code).padStart(DIGITS, "0");
};

export const totpStep = (now = Date.now()) => Math.floor(now / PERIOD_MS);

export const totpCode = (secret, now = Date.now()) =>
  hotp(secret, totpStep(now));

/**
 * Returns the time step matched by `code`, or null. Steps up to `lastStep`
 * are refused, so that an intercepted code can't be replayed.
 */
export const verifyTotp = (secret, code, lastStep = 0, now = Date.now()) => {
  const normalized = String(code ?? "").replace(/\s/g, "");
  if (!secret || !/^\d{6}$/.test(normalized)) {
    return null;
  }
  const current = totpStep(now);
  for (let step = current - WINDOW; step <= current + WINDOW; step++) {
    if (
      step > lastStep &&
      crypto.timingSafeEqual(
        Buffer.from(hotp(secret, step)),
        Buffer.from(normalized),
      )
    ) {
      return step;
    }
  }
  return null;
};

/** the URL encoded in the QR code scanned by authenticator apps */
export const getOtpAuthUri = (secret, username) => {
  const label = encodeURIComponent(`${ISSUER}:${username}`);
  const params = new URLSearchParams({
    secret,
    issuer: ISSUER,
    algorithm: "SHA1",
    digits: String(DIGITS),
    period: String(PERIOD_MS / 1000),
  });
  return `otpauth://totp/${label}?${params}`;
};

// users
// -----------------------------------------------------------------------------

const normalizeRecoveryCode = (code) =>
  String(code ?? "")
    .replace(/[\s-]/g, "")
    .toLowerCase();

const hashRecoveryCode = (code) =>
  crypto.createHash("sha256").update(normalizeRecoveryCode(code)).digest("hex");

/** replaces the user's recovery codes, returns the new ones (shown once) */
export const generateRecoveryCodes = (db, userId) => {
  const codes = Array.from({ length: RECOVERY_CODE_COUNT }, () => {
    const raw = base32Encode(crypto.randomBytes(7)).slice(0, 10).toLowerCase();
    return `${raw.slice(0, 5)}-${raw.slice(5)}`;
  });
  transaction(db, () => {
    db.prepare("DELETE FROM recovery_codes WHERE user_id = ?").run(userId);
    const insert = db.prepare(
      "INSERT INTO recovery_codes (user_id, code_hash) VALUES (?, ?)",
    );
    for (const code of codes) {
      insert.run(userId, hashRecoveryCode(code));
    }
  });
  return codes;
};

export const countRecoveryCodes = (db, userId) =>
  db
    .prepare("SELECT COUNT(*) AS count FROM recovery_codes WHERE user_id = ?")
    .get(userId).count;

export const enableTotp = (db, userId, secret, step) => {
  db.prepare(
    "UPDATE users SET totp_secret = ?, totp_last_step = ? WHERE id = ?",
  ).run(secret, step, userId);
  return generateRecoveryCodes(db, userId);
};

export const disableTotp = (db, userId) => {
  transaction(db, () => {
    db.prepare(
      "UPDATE users SET totp_secret = NULL, totp_last_step = 0 WHERE id = ?",
    ).run(userId);
    db.prepare("DELETE FROM recovery_codes WHERE user_id = ?").run(userId);
  });
};

/**
 * Checks a code typed by `user` (a database row): a code of their
 * authenticator app, or one of their recovery codes (then used up).
 */
export const checkSecondFactor = (db, user, code) => {
  if (!user.totp_secret) {
    return false;
  }
  const step = verifyTotp(user.totp_secret, code, user.totp_last_step);
  if (step !== null) {
    db.prepare("UPDATE users SET totp_last_step = ? WHERE id = ?").run(
      step,
      user.id,
    );
    return true;
  }
  const { changes } = db
    .prepare("DELETE FROM recovery_codes WHERE user_id = ? AND code_hash = ?")
    .run(user.id, hashRecoveryCode(code));
  return changes > 0;
};
